<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import { dataApi } from '../api';
import { apiUrl } from '../api/config';
import { session } from '../lib/session';
import '../styles/pending-balances.css';

const pageSize=15;
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const rows=ref([]),branches=ref([]),loading=ref(false),error=ref(''),notice=ref(''),page=ref(1),sortKey=ref('due'),sortDir=ref('desc'),mode=ref('HO');
const branch=ref(''),employee=ref(''),status=ref(''),age=ref(''),from=ref(''),to=ref(''),minDue=ref(''),search=ref(''),saving=ref({});
const statuses=[['PENDING','Not yet updated'],['COLLECTED','Already collected'],['PARTIAL','Part collected'],['COMMITTED','Will collect'],['NOTCOLL','Not collectable'],['DISPUTE','Disputed / on hold']];
const reasons=['Client not reachable / number invalid','Client refused to pay','Service discontinued by client','Duplicate or wrong billing entry','Discount agreed but not adjusted','Refund / package cancelled case','Client shifted city / not traceable','Legal or medical complaint case','Other (explain in remark)'];
const modes=['Cash','UPI','Card','Bank transfer','Cheque'];
let controller,alive=true,saveTimers=new Map();
const money=v=>'₹'+Number(v||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
const dateText=v=>v?new Date(`${String(v).slice(0,10)}T00:00:00`).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}):'—';
const words=v=>String(v||'').trim().split(/\s+/).filter(Boolean);
const filtered=computed(()=>{let list=rows.value.filter(r=>!employee.value||r.emp===employee.value).filter(r=>!status.value||r.st===status.value).filter(r=>{if(age.value==='')return true;const bucket=Number(r.age)<=30?0:Number(r.age)<=90?1:2;return String(bucket)===age.value;});if(sortKey.value){const k=sortKey.value;list=[...list].sort((a,b)=>{let x=a[k],y=b[k];if(['due','invAmt','paid','colAmt','cmtAmt','age'].includes(k)){x=Number(x)||0;y=Number(y)||0;}else{x=String(x||'').toLowerCase();y=String(y||'').toLowerCase();}const c=x>y?1:x<y?-1:0;return sortDir.value==='asc'?c:-c;});}return list;});
const pageCount=computed(()=>Math.max(1,Math.ceil(filtered.value.length/pageSize)));
const pageRows=computed(()=>filtered.value.slice((page.value-1)*pageSize,page.value*pageSize));
const totals=computed(()=>{const result={gross:0,collected:0,committed:0,writeoff:0,dispute:0,pending:0,done:0};for(const r of filtered.value){const due=Number(r.due)||0,c=Number(r.colAmt)||0,m=Number(r.cmtAmt)||0;result.gross+=due;if(r.st==='COLLECTED')result.collected+=c||due;else if(r.st==='PARTIAL'){result.collected+=c;result.committed+=m;}else if(r.st==='COMMITTED')result.committed+=m;else if(r.st==='NOTCOLL')result.writeoff+=due;else if(r.st==='DISPUTE')result.dispute+=due;else result.pending+=due;if(r.st!=='PENDING')result.done++;}result.real=result.gross-result.collected-result.writeoff;return result;});
const employees=computed(()=>[...new Set(rows.value.map(r=>r.emp).filter(Boolean))].sort((a,b)=>a.localeCompare(b)));
function validate(r){const c=Number(r.colAmt)||0,m=Number(r.cmtAmt)||0;if(c<0||m<0||c>r.due||m>r.due||c+m>r.due+.01)return'Collection and promise amounts cannot exceed the ERP balance.';if(['COLLECTED','PARTIAL'].includes(r.st)&&(!(c>0)||!r.mode))return'Collected amount and payment mode are required.';if(['COLLECTED','PARTIAL'].includes(r.st)&&r.colDate!==today())return'Collected date must be today.';if(['COMMITTED','PARTIAL'].includes(r.st)&&(!(m>0)||!r.cmtDate||r.cmtDate<today()))return'Enter a positive promise amount and today or a future date.';if(r.st==='COLLECTED'&&Math.abs(c-r.due)>.01)return'Full collection must equal the ERP balance.';if(r.st==='NOTCOLL'&&(!r.reason||words(r.remark).length<3))return'Choose a reason and enter at least three remark words.';if(r.st==='DISPUTE'&&words(r.remark).length<3)return'Enter at least three words describing the dispute.';if(words(r.remark).length>25)return'Remarks are limited to 25 words.';return'';}
async function reload(){controller?.abort();const current=new AbortController();controller=current;loading.value=true;error.value='';notice.value='';page.value=1;try{const args={branch:branch.value,from:from.value,to:to.value,min_due:minDue.value,q:search.value.trim(),sort_by:sortKey.value,sort_dir:sortDir.value,limit:1500};const response=await dataApi('dues_recovery_data',args,{signal:current.signal});if(!alive||controller!==current)return;const data=response.message||{};rows.value=(data.rows||[]).map(r=>({...r,invAmt:Number(r.invAmt)||0,paid:Number(r.paid)||0,due:Number(r.due)||0,colAmt:r.colAmt===''?'':String(Number(r.colAmt)||0),cmtAmt:r.cmtAmt===''?'':String(Number(r.cmtAmt)||0)}));branches.value=data.branches||[];if(mode.value==='BR'&&!branch.value&&branches.value.length===1)branch.value=branches.value[0].branch;notice.value=`${rows.value.length.toLocaleString('en-IN')} invoices loaded. Backend returns up to 1,500 rows per request.`;}catch(e){if(alive&&controller===current&&e.name!=='AbortError'){error.value=e.message;rows.value=[];}}finally{if(alive&&controller===current)loading.value=false;}}
function setField(r,key,value){if(key==='st'){r.st=value;if(!['COLLECTED','PARTIAL'].includes(value)){r.colAmt='';r.colDate='';r.mode='';}if(!['PARTIAL','COMMITTED'].includes(value)){r.cmtAmt='';r.cmtDate='';}if(value!=='NOTCOLL')r.reason='';if(value==='COLLECTED'){r.colAmt=String(r.due);r.colDate=today();}if(value==='COMMITTED'&&!r.cmtAmt)r.cmtAmt=String(r.due);}else r[key]=value;}
function saveRow(r){clearTimeout(saveTimers.get(r.inv));saving.value={...saving.value,[r.inv]:'pending'};const timer=setTimeout(async()=>{const problem=validate(r);if(problem){saving.value={...saving.value,[r.inv]:problem};return;}try{const body=new URLSearchParams({invoice_no:r.inv,branch:r.branch,manager_status:r.st,collected_amount:r.colAmt||0,collected_on:r.colDate||'',mode_of_payment:r.mode||'',committed_amount:r.cmtAmt||0,committed_by:r.cmtDate||'',reason:r.reason||'',remark:r.remark||''});const response=await fetch(apiUrl('/api/method/dues_recovery_save'),{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded','X-Frappe-CSRF-Token':session.csrf_token||''},body:body.toString()});const result=await response.json();if(!response.ok||!result.message?.ok)throw Error(result.message?.error||'Save failed.');saving.value={...saving.value,[r.inv]:'saved'};}catch(e){saving.value={...saving.value,[r.inv]:e.message};}},400);saveTimers.set(r.inv,timer);}
function update(r,key,value){setField(r,key,value);saveRow(r);}
function sort(key){if(sortKey.value===key)sortDir.value=sortDir.value==='asc'?'desc':'asc';else{sortKey.value=key;sortDir.value=['due','invAmt','paid','age','nextDue'].includes(key)?'desc':'asc';}reload();}
function reset(){branch.value=employee.value=status.value=age.value=from.value=to.value=minDue.value=search.value='';reload();}
function checkPending(){const count=filtered.value.filter(r=>r.st==='PENDING'||validate(r)).length;notice.value=count?`${count} rows still need complete updates.`:`All ${filtered.value.length} rows are complete.`;}
function printReport(){window.print();}
function csvCell(v){const s=String(v??'');return/[",\r\n]/.test(s)?`"${s.replace(/"/g,'""')}"`:s;}
function exportCsv(){const heads=['Branch','Client','Mobile','Booked By','Practitioner','Invoice','Invoice Date','Service','Invoice Amount','Paid','Due','Next Due','Age Days','Manager Status','Collected','Collected Date','Mode','Will Collect','Promise Date','Reason','Remark'];const data=filtered.value.map(r=>[r.branch,r.client,r.mobile,r.emp,r.practitioner,r.inv,r.invDate,r.service,r.invAmt,r.paid,r.due,r.nextDue,r.age,r.st,r.colAmt,r.colDate,r.mode,r.cmtAmt,r.cmtDate,r.reason,r.remark]);const blob=new Blob(['\ufeff'+[heads,...data].map(row=>row.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`LIFE_Pending_Dues_${branch.value||'ALL'}_${today()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
onMounted(reload);
onBeforeUnmount(()=>{alive=false;controller?.abort();for(const timer of saveTimers.values())clearTimeout(timer);});
</script>

<template>
  <main class="pending-balances"><header class="pb-header"><div><span>COLLECTIONS &amp; RECOVERY</span><h1>Pending Balances</h1><p>Live invoice balances, branch follow-up, and manager collection updates</p></div><button :disabled="loading" @click="reload">{{ loading?'Loading…':'↻ Refresh' }}</button></header>
    <section class="pb-filters"><label>View<select v-model="mode" @change="reload"><option value="HO">Head Office · permitted branches</option><option value="BR">Branch Manager view</option></select></label><label>Branch<select v-model="branch" :disabled="mode==='BR'&&branches.length===1" @change="reload"><option value="">All permitted branches</option><option v-for="b in branches" :key="b.branch" :value="b.branch">{{ b.branch }} · {{ b.n }} open</option></select></label><label>Booked By<select v-model="employee" @change="page=1"><option value="">All employees</option><option v-for="e in employees" :key="e">{{ e }}</option></select></label><label>Status<select v-model="status" @change="page=1"><option value="">All statuses</option><option v-for="[key,label] in statuses" :key="key" :value="key">{{ label }}</option></select></label><label>Ageing<select v-model="age" @change="page=1"><option value="">All ageing</option><option value="0">0–30 days</option><option value="1">31–90 days</option><option value="2">90+ days</option></select></label><label>Due date from<input v-model="from" type="date"></label><label>Due date to<input v-model="to" type="date"></label><label>Minimum due (₹)<input v-model="minDue" type="number" min="0" placeholder="Any amount"></label><label class="pb-search">Client, mobile, invoice<input v-model="search" placeholder="Search live data…"></label><div class="pb-filter-actions"><button @click="reset">Clear filters</button><button class="pb-primary" :disabled="loading" @click="reload">Apply filters</button></div></section>
    <p v-if="error" class="pb-error" role="alert">{{ error }}</p><p v-else-if="notice" class="pb-notice" role="status">{{ notice }}</p>
    <section class="pb-kpis"><article><span>Gross pending due</span><strong>{{ money(totals.gross) }}</strong><small>{{ filtered.length }} invoices in view</small></article><article><span>Updates completed</span><strong>{{ filtered.length?Math.round(totals.done/filtered.length*100):0 }}%</strong><small>{{ totals.done }} of {{ filtered.length }} rows updated</small></article><article><span>Collected now</span><strong>{{ money(totals.collected) }}</strong><small>Collected against these invoices</small></article><article><span>Committed</span><strong>{{ money(totals.committed) }}</strong><small>Promised with a date</small></article><article><span>Proposed removal</span><strong>{{ money(totals.writeoff) }}</strong><small>Requires Head Office approval</small></article><article><span>Real balance left</span><strong>{{ money(totals.real) }}</strong><small>After collection and proposed removal</small></article></section>
    <section class="pb-register"><div class="pb-register-title"><div><h2>Invoice Recovery Register</h2><p>ERP columns are read-only. Manager updates save automatically after each change.</p></div><div><button @click="checkPending">Check pending updates</button><button @click="exportCsv">Download CSV</button><button @click="printReport">Print</button></div></div><div class="pb-table-scroll"><table><thead><tr><th @click="sort('branch')">Branch</th><th @click="sort('client')">Client / Mobile</th><th @click="sort('emp')">Booked By</th><th @click="sort('inv')">Invoice</th><th @click="sort('invAmt')">Invoice Amount</th><th @click="sort('paid')">Paid</th><th @click="sort('due')">Due</th><th @click="sort('nextDue')">Next Due / Age</th><th>Manager Status</th><th>Collected ₹</th><th>Collected on</th><th>Mode</th><th>Will collect ₹</th><th>By date</th><th>Reason</th><th>Remark</th><th>Save state</th></tr></thead><tbody><tr v-for="r in pageRows" :key="r.inv"><td>{{ r.branch }}</td><td><strong>{{ r.client }}</strong><small>{{ r.mobile||'—' }}</small></td><td>{{ r.emp||'—' }}<small>{{ r.practitioner||'' }}</small></td><td>{{ r.inv }}<small>{{ dateText(r.invDate) }}</small></td><td>{{ money(r.invAmt) }}</td><td>{{ money(r.paid) }}</td><td class="pb-due">{{ money(r.due) }}</td><td>{{ dateText(r.nextDue) }}<small>{{ r.age }} days overdue</small></td><td><select :value="r.st" @change="update(r,'st',$event.target.value)"><option v-for="[key,label] in statuses" :key="key" :value="key">{{ label }}</option></select></td><td><input :value="r.colAmt" type="number" min="0" step="0.01" :max="r.due" :disabled="!['COLLECTED','PARTIAL'].includes(r.st)" @change="update(r,'colAmt',$event.target.value)"></td><td><input :value="r.colDate" type="date" :disabled="!['COLLECTED','PARTIAL'].includes(r.st)" @change="update(r,'colDate',$event.target.value)"></td><td><select :value="r.mode" :disabled="!['COLLECTED','PARTIAL'].includes(r.st)" @change="update(r,'mode',$event.target.value)"><option value="">Choose</option><option v-for="m in modes" :key="m">{{ m }}</option></select></td><td><input :value="r.cmtAmt" type="number" min="0" step="0.01" :max="r.due" :disabled="!['PARTIAL','COMMITTED'].includes(r.st)" @change="update(r,'cmtAmt',$event.target.value)"></td><td><input :value="r.cmtDate" type="date" :disabled="!['PARTIAL','COMMITTED'].includes(r.st)" @change="update(r,'cmtDate',$event.target.value)"></td><td><select :value="r.reason" :disabled="r.st!=='NOTCOLL'" @change="update(r,'reason',$event.target.value)"><option value="">Choose reason</option><option v-for="reason in reasons" :key="reason">{{ reason }}</option></select></td><td><textarea :value="r.remark" maxlength="220" placeholder="Up to 25 words" :disabled="r.st==='PENDING'" @change="update(r,'remark',$event.target.value)"></textarea></td><td><span class="pb-save" :class="{saved:saving[r.inv]==='saved',failed:!!saving[r.inv]&&saving[r.inv]!=='saved'&&saving[r.inv]!=='pending'}">{{ saving[r.inv]==='pending'?'Saving…':saving[r.inv]==='saved'?'Saved':saving[r.inv]||'—' }}</span></td></tr><tr v-if="!loading&&!pageRows.length"><td colspan="17" class="pb-empty">No open invoices match these filters.</td></tr></tbody></table></div><footer class="pb-pager"><span>Page {{ page }} of {{ pageCount }} · {{ filtered.length }} filtered rows · API cap 1,500</span><div><button :disabled="page<=1" @click="page=1">First</button><button :disabled="page<=1" @click="page--">Previous</button><button :disabled="page>=pageCount" @click="page++">Next</button><button :disabled="page>=pageCount" @click="page=pageCount">Last</button></div></footer></section>
  </main>
</template>
